function stream(seed) {
  return { s: seed >>> 0 };
}
function next(st) {
  st.s = st.s + 1831565813 >>> 0;
  let t = st.s;
  t = Math.imul(t ^ t >>> 15, t | 1);
  t ^= t + Math.imul(t ^ t >>> 7, t | 61);
  return ((t ^ t >>> 14) >>> 0) / 4294967296;
}
function roll(st, lo, hi) {
  return lo + Math.floor(next(st) * (hi - lo + 1));
}
function nextFloorSeed(seed) {
  return Math.imul(seed >>> 0, 1664525) + 1013904223 >>> 0;
}
function shuffle(st, a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(next(st) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
var shuffled = (st, a) => shuffle(st, a.slice());
var pick = (st, a) => a[Math.floor(next(st) * a.length)];
function weighted(st, rows, weightOf2 = (r) => r.weight, { edge: edge2 = "lt" } = {}) {
  let w = next(st) * rows.reduce((s, r) => s + weightOf2(r), 0);
  for (const r of rows) {
    w -= weightOf2(r);
    if (edge2 === "le" ? w <= 0 : w < 0) return r;
  }
  return rows[rows.length - 1];
}

