// forge-rewrite/src/ui/model/version-check.js
var QUIET_CHECK = { state: () => ({ message: "", latest: null }), check: () => {
}, install: () => {
}, itch: () => false, watch: () => () => {
}, titleStatus: () => "" };
var versionCheck = (deps) => deps?.version ?? QUIET_CHECK;

// forge-rewrite/src/ui/screens/about.js
var PARAS = [
  "A turn-based roguelike. Choose a race and a class, swear to a god if you dare, and fight down twenty-five floors through five biomes, gathering the six elements to shape your gear and your magic.",
  "Made by Justin Hoffman, who designs it and directs every creature, map and sound.",
  "Built with AI assistance for the art, the music and the code."
];
function buildAbout(kit, area2) {
  const title2 = kit.text("Forge of the Elements", { size: 26, font: "display", fill: kit.accent, wrap: area2.w });
  const body2 = PARAS.map((p, i) => kit.text(p, { size: 16, fill: i ? color.ash : color.ink, wrap: area2.w }));
  return stack([title2, ...body2], space.betweenSections);
}
var notesAt = { pick: 0, page: 0 };
function buildVersion(kit, area2, ctx) {
  const { state: versionState, check: checkVersion, install: installUpdate, itch: itchUpload, watch: watchVersion } = versionCheck(ctx.deps);
  const s = versionState(), built = { latest: !!s.latest, installing: s.installing, validated: s.validated };
  const status = kit.text(`${VERSION} \xB7 ${s.message}`, { size: 14, fill: s.latest ? kit.accent : color.ash, wrap: area2.w });
  const plates = [];
  const plateH = Math.max(36, kit.target);
  if (s.latest && !itchUpload()) plates.push(kit.plateButton(s.installing ? "Installing\u2026" : "Install update", () => {
    if (s.validated && !s.installing) installUpdate();
  }, { h: plateH, size: 16, rank: "prominent" }));
  plates.push(kit.plateButton("Check again", () => {
    ctx.deps?.cue?.("ui-click");
    checkVersion();
  }, { h: plateH, size: 16 }));
  plates.forEach((p) => {
    p.label = "version-" + p.label.toLowerCase().replace(/\W+/g, "-");
  });
  const how = kit.text(itchUpload() ? "To update this copy, reload the itch.io game page. Saved games and settings are kept." : "Reloading to update keeps your saved games and settings.", { size: 14, fill: color.dim, wrap: area2.w });
  const actions = new Container();
  flow(plates, area2.w, space.betweenRows, space.betweenRows);
  actions.addChild(...plates);
  const head = stack([status, actions, how], space.betweenRows);
  const pick5 = Math.min(notesAt.pick, PATCHES.length - 1);
  const names = PATCHES.map((p, i) => Object.assign(kit.button(p.version, () => {
    ctx.deps?.cue?.("ui-click");
    notesAt.pick = i;
    notesAt.page = 0;
    ctx.reopen();
  }, { size: 16, font: "body", tight: !kit.stage.touch, selected: i === pick5 }), { label: "version-" + i }));
  const list = new Container();
  names.forEach((n) => list.addChild(n));
  flow(names, area2.w, space.betweenRows, 0);
  const bullet = kit.size(14) * 1.1;
  const items = PATCHES[pick5].notes.map((words6) => {
    const c = new Container(), dot2 = new Graphics().circle(3, kit.size(14) * 0.7, 2.5).fill(color.dim);
    const t = kit.text(words6, { size: 14, fill: color.ink, wrap: area2.w - bullet });
    t.x = bullet;
    c.addChild(dot2, t);
    return c;
  });
  const top = head.height + space.betweenSections + list.height + space.betweenSections;
  const P20 = kit.stage.kind === "P" || kit.stage.touch;
  const room = area2.h - top - kit.target - space.betweenRows;
  const pages = [[]];
  let used = 0;
  for (const it of items) {
    const h = it.height + space.betweenRows;
    if (!P20 && pages.at(-1).length && used + h > room) {
      pages.push([]);
      used = 0;
    }
    pages.at(-1).push(it);
    used += h;
  }
  const page2 = Math.min(notesAt.page, pages.length - 1);
  items.filter((it) => !pages[page2].includes(it)).forEach((it) => it.destroy({ children: true }));
  const body2 = stack(pages[page2], space.betweenRows);
  const parts = [head, list, body2];
  if (pages.length > 1) {
    const go = (n) => {
      notesAt.page = n;
      ctx.reopen();
    };
    const prev = Object.assign(kit.button("\u2039", () => go(Math.max(0, page2 - 1)), { size: 26, font: "body", dim: page2 === 0 }), { label: "page-prev" });
    const next2 = Object.assign(kit.button("\u203A", () => go(Math.min(pages.length - 1, page2 + 1)), { size: 26, font: "body", dim: page2 === pages.length - 1 }), { label: "page-next" });
    const nav = row([prev, kit.text(`${page2 + 1} / ${pages.length}`, { size: 14, fill: color.ash }), next2], space.betweenRows);
    nav.x = Math.round((area2.w - nav.width) / 2);
    parts.push(nav);
  }
  const root = stack(parts, space.betweenSections);
  const unwatch = watchVersion((v) => {
    if (root.destroyed) return;
    if (!!v.latest !== built.latest || v.installing !== built.installing || v.validated !== built.validated) {
      setTimeout(() => {
        if (!root.destroyed) ctx.reopen();
      }, 0);
      return;
    }
    status.text = `${VERSION} \xB7 ${v.message}`;
  });
  root.on("destroyed", unwatch);
  return root;
}

// forge-rewrite/src/ui/core/text-entry.js
function editText(stage, rect2, value3, o) {
  const el = (
    /** @type {HTMLInputElement|null} */
    document.getElementById("text-entry")
  );
  if (!el) return () => {
  };
  const css = { left: stage.ox + rect2.x * stage.s, top: stage.oy + rect2.y * stage.s, width: rect2.w * stage.s, height: rect2.h * stage.s };
  Object.assign(el.style, { left: css.left + "px", top: css.top + "px", width: css.width + "px", height: css.height + "px", fontSize: Math.max(16, css.height * 0.5) + "px" });
  el.maxLength = o.max ?? 24;
  el.value = value3;
  const input = () => o.onInput(el.value);
  const key2 = (e) => {
    if (e.key === "Enter" || e.key === "Escape") {
      e.preventDefault();
      el.blur();
    }
  };
  const done = () => {
    stop();
    o.onDone(el.value.trim());
  };
  function stop() {
    el.removeEventListener("input", input);
    el.removeEventListener("keydown", key2);
    el.removeEventListener("blur", done);
    el.style.left = "-9999px";
  }
  el.addEventListener("input", input);
  el.addEventListener("keydown", key2);
  el.addEventListener("blur", done);
  el.focus();
  el.setSelectionRange(el.value.length, el.value.length);
  return stop;
}

